var adminjs={categoryTree:function(termLink,thisParent,nextLevelReferer,returnLinkReferer,returnLinkParent){if("edit-category"!=pagenow)return!1;jQuery(".row-actions").each((function(){var currentId=parseInt(jQuery(this).parent().parent().attr("id").replace("tag-",""));if(currentId==thisParent)if(returnLinkReferer.length>1)var actionText="<span> | <a href='"+termLink+"&imwp_parent="+returnLinkParent+"&referer="+returnLinkReferer.toString()+"&orderby=term_id'>返回上一层</a></span>";else if(returnLinkReferer.length>0)var actionText="<span> | <a href='"+termLink+"&imwp_parent="+returnLinkParent+"&referer="+returnLinkReferer.toString()+"'>返回上一层</a></span>";else var actionText="<span> | <a href='"+termLink+"&imwp_parent="+returnLinkParent+"'>返回上一层</a></span>";else if(nextLevelReferer.length>1)var actionText="<span> | <a href='"+termLink+"&imwp_parent="+currentId+"&referer="+nextLevelReferer.toString()+"&orderby=term_id'>仅展开该分类</a></span>";else var actionText="<span> | <a href='"+termLink+"&imwp_parent="+currentId+"&referer="+nextLevelReferer.toString()+"'>仅展开该分类</a></span>";jQuery(this).append(actionText)}))},addChangePostOrderButton:function(){if("edit-post"!=pagenow)return!1;var referer=encodeURIComponent(jQuery("#wp-admin-canonical").attr("href"));jQuery("#the-list .row-actions").delegate(".wpnovo-move-to","click",(function(){var res=prompt("移动到哪一章前面? (比如移动到第一章前，则填写1)"),postID=jQuery(this).attr("data-post-id");res&&(window.location=ajaxurl+"?action=post_move&post_id="+postID+"&to="+res+"&referer="+referer)})),jQuery("#the-list .row-actions").each((function(){var postId=parseInt(jQuery(this).parent().parent().attr("id").replace("post-","")),moveDown='<a href="'+ajaxurl+"?action=post_move_down&post_id="+postId+"&referer="+referer+'">下移</a>',moveUp='<a href="'+ajaxurl+"?action=post_move_up&post_id="+postId+"&referer="+referer+'">上移</a>',moveAfterPos='<a style="cursor:pointer" class="wpnovo-move-to" data-post-id="'+postId+'">移到N章前</a>';jQuery(this).append("<span > | "+moveUp+" | </span> <span>"+moveDown+"</span> | <span>"+moveAfterPos+"</span>")}))}};